  "slug": "tabler-clipboard-check",
  "family": "tabler",
  "name": "clipboard-check",
  "category": "Files",
  "motion": "copy",
  "component": "createTablerClipboardCheckIcon"
};

export function createTablerClipboardCheckIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
